<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); foreach(File::allFiles(app_path("Models")) as $f) { $c = "App\\Models\\".str_replace("/", "\\", str_replace(".php", "", $f->getRelativePathname())); try { if(class_exists($c) && (new ReflectionClass($c))->isInstantiable()) { $m = new $c; $t = $m->getTable(); $cols = Schema::getColumnListing($t); $fill = $m->getFillable(); $diff = array_diff($fill, $cols); if(!empty($diff)) echo "[WARN] $c -> Missing in DB: ".implode(",", $diff)."\n"; } } catch(Exception $e) {} }
